lume-1.ts","../../src/icons/volume-2.ts","../../src/icons/volume-off.ts","../../src/icons/volume-x.ts","../../src/icons/volume.ts","../../src/icons/vote.ts","../../src/icons/wallet-cards.ts","../../src/icons/wallet-minimal.ts","../../src/icons/wallet.ts","../../src/icons/wand-sparkles.ts","../../src/icons/wallpaper.ts","../../src/icons/wand.ts","../../src/icons/warehouse.ts","../../src/icons/washing-machine.ts","../../src/icons/watch.ts","../../src/icons/waves-arrow-down.ts","../../src/icons/waves-arrow-up.ts","../../src/icons/waves-horizontal.ts","../../src/icons/waves-vertical.ts","../../src/icons/waves-ladder.ts","../../src/icons/waypoints.ts","../../src/icons/webcam-off.ts","../../src/icons/webhook-off.ts","../../src/icons/webcam.ts","../../src/icons/webhook.ts","../../src/icons/weight-tilde.ts","../../src/icons/weight.ts","../../src/icons/wheat-off.ts","../../src/icons/wheat.ts","../../src/icons/whole-word.ts","../../src/icons/whistle.ts","../../src/icons/wifi-cog.ts","../../src/icons/wifi-high.ts","../../src/icons/wifi-low.ts","../../src/icons/wifi-off.ts","../../src/icons/wifi-pen.ts","../../src/icons/wifi-zero.ts","../../src/icons/wifi-sync.ts","../../src/icons/wifi.ts","../../src/icons/wind-arrow-down.ts","../../src/icons/wine-off.ts","../../src/icons/wind.ts","../../src/icons/wine.ts","../../src/icons/worm.ts","../../src/icons/wrench-off.ts","../../src/icons/workflow.ts","../../src/icons/wrench.ts","../../src/icons/x-line-top.ts","../../src/icons/x.ts","../../src/icons/zap-off.ts","../../src/icons/zap.ts","../../src/icons/zodiac-aquarius.ts","../../src/icons/zodiac-aries.ts","../../src/icons/zodiac-cancer.ts","../../src/icons/zodiac-capricorn.ts","../../src/icons/zodiac-gemini.ts","../../src/icons/zodiac-leo.ts","../../src/icons/zodiac-ophiuchus.ts","../../src/icons/zodiac-libra.ts","../../src/icons/zodiac-pisces.ts","../../src/icons/zodiac-sagittarius.ts","../../src/icons/zodiac-scorpio.ts","../../src/icons/zodiac-taurus.ts","../../src/icons/zodiac-virgo.ts","../../src/icons/zoom-out.ts","../../src/icons/zoom-in.ts"],"sourcesContent":["const defaultAttributes = {\n  xmlns: 'http://www.w3.org/2000/svg',\n  width: 24,\n  height: 24,\n  viewBox: '0 0 24 24',\n  fill: 'none',\n  stroke: 'currentColor',\n  'stroke-width': 2,\n  'stroke-linecap': 'round',\n  'stroke-linejoin': 'round',\n} as const;\n\nexport default defaultAttributes;\n","/**\n * Merges classes into a single string\n *\n * @param {array} classes\n * @returns {string} A string of classes\n */\nexport const mergeClasses = <ClassType = string | undefined | null>(...classes: ClassType[]) =>\n  classes\n    .filter((className, index, array) => {\n      return (\n        Boolean(className) &&\n        (className as string).trim() !== '' &&\n        array.indexOf(className) === index\n      );\n    })\n    .join(' ')\n    .trim();\n","import type { LucideBuildParams, LucideIconData, LucideIconNode, SVGProps } from './types';\nimport defaultAttributes from './defaultAttributes';\nimport { mergeClasses } from '../utils/mergeClasses';\n\nfunction isDefined<T>(value: T | null | undefined): value is T {\n  return value !== null && value !== undefined;\n}\n\n/**\n * Creates a Lucide icon node (an svgson-like format) from a Lucide icon object.\n *\n * @param icon The icon to build.\n * @param params Additional build parameters.\n */\nfunction buildLucideIconNode(icon: LucideIconData, params: LucideBuildParams = {}): LucideIconNode {\n  const attributeNames = params.attributeNames ?? {};\n  const getAttributeName = (attributeName: string) =>\n    attributeNames[attributeName] ?? attributeName;\n\n  const viewBoxWidth = icon.size ?? icon.width ?? defaultAttributes['width'];\n  const viewBoxHeight = icon.size ?? icon.height ?? defaultAttributes['height'];\n  const aliasClassNames =\n    icon.aliases\n      ?.filter((alias: string): alias is string => typeof alias === 'string' && alias.trim() !== '')\n      .map((alias: string) => `lucide-${alias}`) ?? [];\n  const iconClassNames = [...(icon.name ? [`lucide-${icon.name}`] : []), ...aliasClassNames];\n  const classNamesFromClassName = params.className?.split(' ').filter(Boolean) ?? [];\n  const className =\n    params.includeDefaultClasses === false\n      ? mergeClasses(...classNamesFromClassName)\n      : mergeClasses('lucide', ...iconClassNames, ...classNamesFromClassName);\n\n  const calculatedStrokeWidth = params.absoluteStrokeWidth\n    ? (Number(params.strokeWidth ?? defaultAttributes['stroke-width']) *\n        Number(icon.size ?? icon.width ?? defaultAttributes['width'])) /\n      Number(params.size ?? params.width ?? defaultAttributes['width'])\n    : (params.strokeWidth ?? defaultAttributes['stroke-width']);\n\n  const attributes = {\n    ...Object.entries(defaultAttributes).reduce((attrs, [attrName, value]) => {\n      attrs[getAttributeName(attrName)] = value;\n      return attrs;\n    }, {} as SVGProps),\n    ...('color' in params &&\n      params.color && {\n        [getAttributeName('stroke')]: params.color,\n      }),\n    ...('size' in params &&\n      isDefined(params.size) && {\n        [getAttributeName('width')]: params.size,\n        [getAttributeName('height')]: params.size,\n      }),\n    ...('width' in params &&\n      isDefined(params.width) && {\n        [getAttributeName('width')]: params.width,\n      }),\n    ...('height' in params &&\n      isDefined(params.height) && {\n        [getAttributeName('height')]: params.height,\n      }),\n    [getAttributeName('stroke-width')]: calculatedStrokeWidth,\n    ...(className && {\n      [getAttributeName('class')]: className,\n    }),\n    [getAttributeName('viewBox')]: `0 0 ${viewBoxWidth} ${viewBoxHeight}`,\n    ...(params.hasA11yProp === false\n      ? {\n          [getAttributeName('aria-hidden')]: 'true',\n        }\n      : {}),\n    ...('attributes' in params && params.attributes),\n  };\n\n  return [\n    'svg',\n    attributes,\n    icon.node.map((child): LucideIconNode => {\n      const [name, attrs, children] = child;\n      const nextAttrs = params.nonScalingStroke\n        ? { [getAttributeName('vector-effect')]: 'non-scaling-stroke', ...attrs }\n        : attrs;\n\n      return children ? [name, nextAttrs, children] : [name, nextAttrs];\n    }),\n  ];\n}\n\nexport default buildLucideIconNode;\n","import buildLucideIconNode from './buildLucideIconNode';\nimport type { LucideBuildParams, LucideIconData, LucideIconNode } from './types';\n\n/**\n * Creates a React-compatible Lucide icon node (an svgson-like format) from a Lucide icon object.\n *\n * @param icon The icon to build.\n * @param params Additional build parameters.\n */\nfunction buildLucideIconForReact(\n  icon: LucideIconData,\n  params: LucideBuildParams = {},\n): LucideIconNode {\n  return buildLucideIconNode(icon, {\n    ...params,\n    attributeNames: {\n      ...params.attributeNames,\n      class: 'className',\n      'stroke-width': 'strokeWidth',\n      'stroke-linecap': 'strokeLinecap',\n      'stroke-linejoin': 'strokeLinejoin',\n      'vector-effect': 'vectorEffect',\n    },\n  });\n}\n\nexport default buildLucideIconForReact;\n","/**\n * Check if a component has an accessibility prop\n *\n * @param {object} props\n * @returns {boolean} Whether the component has an accessibility prop\n */\nexport const hasA11yProp = (props: object) => {\n  for (const prop in props) {\n    if (prop.startsWith('aria-') || prop === 'role' || prop === 'title') {\n      return true;\n    }\n  }\n\n  return false;\n};\n","/**\n * Converts string to camel case\n *\n * @param {string} string\n * @returns {string} A camelized string\n */\nexport const toCamelCase = <T extends string>(string: T) => {\n  let out = '';\n  let upperNext = false;\n\n  for (const ch of string) {\n    if (ch === '-' || ch === '_' || ch <= ' ') {\n      upperNext = out.length > 0;\n      continue;\n    }\n\n    if (out.length === 0) {\n      out += ch.toLowerCase();\n    } else {\n      out += upperNext ? ch.toUpperCase() : ch;\n    }\n\n    upperNext = false;\n  }\n\n  return out as string;\n};\n","/**\n * Converts string to kebab case\n *\n * @param {string} string\n * @returns {string} A kebabized string\n */\nexport const toKebabCase = (string: string) =>\n  string?.replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase();\n","import { toKebabCase } from './toKebabCase';\nimport type { LucideIconData, LucideIconNode } from '../build/types';\n\n/**\n * Converts legacy `(name, iconNode, aliases?)` icon arguments into icon data object format.\n */\nexport function toLucideIconData(\n  iconName: string,\n  iconNode: LucideIconNode[],\n  aliases: string[] = [],\n): LucideIconData {\n  if (iconNode == null) {\n    throw new Error('[lucide]: iconNode is required when icon name is used');\n  }\n\n  return {\n    name: toKebabCase(iconName),\n    size: 24,\n    node: iconNode,\n    ...(aliases.length > 0 ? { aliases } : {}),\n  };\n}\n","import { CamelToPascal } from '../utility-types';\nimport { toCamelCase } from './toCamelCase';\n\n/**\n * Converts string to pascal case\n *\n * @param {string} string\n * @returns {string} A pascalized string\n */\nexport const toPascalCase = <T extends string>(string: T): CamelToPascal<T> => {\n  const camelCase = toCamelCase(string);\n\n  return (camelCase.charAt(0).toUpperCase() + camelCase.slice(1)) as CamelToPascal<T>;\n};\n","'use client';\n\nimport { createContext, createElement, type ReactNode, useContext, useMemo } from 'react';\nimport { LucideProps } from './types';\n\ntype LucideConfig = {\n  size: number;\n  color: string;\n  strokeWidth: number;\n  /**\n   * @deprecated Use `nonScalingStroke` instead.\n   */\n  absoluteStrokeWidth: boolean;\n  nonScalingStroke: boolean;\n  className: string;\n};\n\nconst LucideContext = createContext<LucideProps>({});\n\ntype LucideProviderProps = {\n  children: ReactNode;\n} & Partial<LucideConfig>;\n\nexport function LucideProvider({\n  children,\n  size,\n  color,\n  strokeWidth,\n  absoluteStrokeWidth,\n  nonScalingStroke,\n  className,\n}: LucideProviderProps) {\n  const value = useMemo(\n    () => ({\n      size,\n      color,\n      strokeWidth,\n      absoluteStrokeWidth,\n      nonScalingStroke,\n      className,\n    }),\n    [size, color, strokeWidth, absoluteStrokeWidth, nonScalingStroke, className],\n  );\n\n  return createElement(LucideContext.Provider, { value }, children);\n}\n\nexport const useLucideContext = () => useContext(LucideContext);\n","'use client';\n\nimport { createElement, forwardRef } from 'react';\nimport { buildLucideIconForReact, hasA11yProp, mergeClasses } from '@lucide/shared';\nimport { LucideIconData, LucideIconNode, LucideProps } from './types';\nimport { useLucideContext } from './context';\n\ntype IconComponentProps = LucideProps &\n  (\n    | {\n        iconNode: LucideIconNode[];\n        icon?: never;\n      }\n    | {\n        icon: LucideIconData;\n        iconNode?: never;\n      }\n  );\n\n/**\n * Lucide icon component\n *\n * @component Icon\n * @param {object} props\n * @param {string} props.color - The color of the icon\n * @param {number} props.size - The size of the icon\n * @param {number} props.strokeWidth - The stroke width of the icon\n * @param {boolean} props.absoluteStrokeWidth - Whether to use absolute stroke width\n * @param {boolean} props.nonScalingStroke - Whether to use non scaling strokes\n * @param {string} props.className - The class name of the icon\n * @param {LucideIconNode[]} props.children - The children of the icon\n * @param {LucideIconNode[]} props.iconNode - The icon node of the icon\n *\n * @returns {ForwardRefExoticComponent} LucideIcon\n */\nconst Icon = forwardRef<SVGSVGElement, IconComponentProps>(\n  (\n    {\n      color,\n      size,\n      width,\n      height,\n      strokeWidth,\n      absoluteStrokeWidth,\n      nonScalingStroke,\n      className = '',\n      children,\n      iconNode = [],\n      icon = {\n        node: iconNode,\n        aliases: [],\n        size: 24,\n      },\n      ...rest\n    },\n    ref,\n  ) => {\n    const {\n      size: contextSize = 24,\n      strokeWidth: contextStrokeWidth = 2,\n      absoluteStrokeWidth: contextAbsoluteStrokeWidth = false,\n      nonScalingStroke: contextNonScalingStroke = false,\n      color: contextColor = 'currentColor',\n      className: contextClass = '',\n    } = useLucideContext() ?? {};\n\n    const hasAccessibleProp = Boolean(children) || hasA11yProp(rest);\n\n    const [name, svgAttributes, builtIconNode = []] = buildLucideIconForReact(icon, {\n      color: color ?? contextColor,\n      width: width ?? size ?? contextSize,\n      height: height ?? size ?? contextSize,\n      strokeWidth: strokeWidth ?? contextStrokeWidth,\n      absoluteStrokeWidth: absoluteStrokeWidth ?? contextAbsoluteStrokeWidth,\n      nonScalingStroke: nonScalingStroke ?? contextNonScalingStroke,\n      className: mergeClasses(contextClass, className),\n      hasA11yProp: hasAccessibleProp,\n      attributes: rest,\n    });\n\n    return createElement(\n      name,\n      {\n        ref,\n        ...svgAttributes,\n      },\n      [\n        ...builtIconNode.map(([tag, attrs]) => createElement(tag, attrs)),\n        ...(Array.isArray(children) ? children : [children]),\n      ],\n    );\n  },\n);\n\nexport default Icon;\n","import { createElement, forwardRef } from 'react';\nimport { toLucideIconData, toPascalCase } from '@lucide/shared';\nimport { LucideIcon, LucideIconData, LucideIconNode, LucideProps } from './types';\nimport Icon from './Icon';\n\n/**\n * Creates a Lucide icon component from icon data.\n *\n * @param icon Icon data object.\n * @returns Lucide icon component.\n */\nfunction createLucideIcon(icon: LucideIconData): LucideIcon;\n\n/**\n * Creates a Lucide icon component from the legacy icon arguments.\n *\n * @param iconName Icon name.\n * @param iconNode Icon node.\n * @param aliases Optional icon aliases.\n * @returns Lucide icon component.\n */\nfunction createLucideIcon(\n  iconName: string,\n  iconNode: Lucid